#include <stdio.h>

int main(void) {
    int n, x[100], h = 0;

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &x[i]);
        if (x[i] > h) h = x[i];
    }

    for (int level = h; level >= 1; level--) {
        for (int i = 0; i < n; i++) {
            if (i > 0) printf(" ");
            printf("%d", x[i] >= level ? 1 : 0);
        }
        printf("\n");
    }

    return 0;
}
